parts.text:
{
  "extractions": [
    {
      "requirement": "Each House shall be the Judge of the Elections, Returns and Qualifications of its own Members",
      "requirement_attributes": {
        "summary": "Each House must judge the elections, returns, and qualifications of its members",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "requirement": "a Majority of each shall constitute a Quorum to do Business",
      "requirement_attributes": {
        "summary": "A majority of each House constitutes a quorum to do business",
        "actor": "a Majority of each",
        "applies_to": ""
      }
    },
    {
      "permission": "a smaller Number may adjourn from day to day",
      "permission_attributes": {
        "summary": "A smaller number than a majority may adjourn from day to day",
        "actor": "a smaller Number",
        "applies_to": ""
      }
    },
    {
      "permission": "may be authorized to compel the Attendance of absent Members",
      "permission_attributes": {
        "summary": "A smaller number may be authorized to compel the attendance of absent members",
        "actor": "a smaller Number",
        "applies_to": ""
      }
    },
    {
      "condition": "in such Manner, and under such Penalties as each House may provide",
      "condition_attributes": {
        "summary": "Compulsion of absent members must follow the manner and penalties provided by each House",
        "actor": "each House",
        "applies_to": "may be authorized to compel the Attendance of absent Members"
      }
    },
    {
      "permission": "each House may provide",
      "permission_attributes": {
        "summary": "Each House may provide the manner and penalties for compelling attendance",
        "actor": "each House",
        "applies_to": ""
      }
    },
    {
      "permission": "Each House may determine the Rules of its Proceedings",
      "permission_attributes": {
        "summary": "Each House may determine the rules of its proceedings",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "permission": "punish its Members for disorderly Behaviour",
      "permission_attributes": {
        "summary": "Each House may punish its members for disorderly behavior",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "permission": "expel a Member",
      "permission_attributes": {
        "summary": "Each House may expel a member",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "condition": "with the Concurrence of two thirds",
      "condition_attributes": {
        "summary": "Expelling a member requires the concurrence of two-thirds",
        "actor": "two thirds",
        "applies_to": "expel a Member"
      }
    },
    {
      "requirement": "Each House shall keep a Journal of its Proceedings",
      "requirement_attributes": {
        "summary": "Each House must keep a journal of its proceedings",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "requirement": "from time to time publish the same",
      "requirement_attributes": {
        "summary": "Each House must publish its journal from time to time",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "exception": "excepting such Parts as may in their Judgment require Secrecy",
      "exception_attributes": {
        "summary": "Parts that require secrecy in their judgment are exempt from publication",
        "actor": "Each House",
        "applies_to": "from time to time publish the same"
      }
    },
    {
      "requirement": "the Yeas and Nays of the Members of either House on any question shall, at the Desire of one fifth of those Present, be entered on the Journal",
      "requirement_attributes": {
        "summary": "The yeas and nays of members on any question must be entered on the journal upon request",
        "actor": "Each House",
        "applies_to": ""
      }
    },
    {
      "condition": "at the Desire of one fifth of those Present",
      "condition_attributes": {
        "summary": "Entering yeas and nays requires the desire of one-fifth of those present",
        "actor": "one fifth of those Present",
        "applies_to": "the Yeas and Nays of the Members of either House on any question shall, at the Desire of one fifth of those Present, be entered on the Journal"
      }
    },
    {
      "prohibition": "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days",
      "prohibition_attributes": {
        "summary": "Neither House may adjourn for more than three days during session without the other House's consent",
        "actor": "Neither House",
        "applies_to": ""
      }
    },
    {
      "condition": "during the Session of Congress",
      "condition_attributes": {
        "summary": "The adjournment limitation applies during the session of Congress",
        "actor": "Congress",
        "applies_to": "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days"
      }
    },
    {
      "condition": "without the Consent of the other",
      "condition_attributes": {
        "summary": "Consent of the other House is required to adjourn for more than three days",
        "actor": "the other",
        "applies_to": "Neither House, during the Session of Congress, shall, without the Consent of the other, adjourn for more than three days"
      }
    },
    {
      "prohibition": "nor to any other Place than that in which the two Houses shall be sitting",
      "prohibition_attributes": {
        "summary": "Neither House may adjourn to any other place than where the two Houses are sitting",
        "actor": "Neither House",
        "applies_to": ""
      }
    }
  ]
}
